/* Grabadora de audio: guarda WAV de 24 kHz, mono, 16 bits */
#include "z.h"
typedef struct { char n[120]; u64 s; } it_t;
static zwin *W; static it_t L[200]; static int n, sel = -1, top, rec, peak, f = -1, gain = 100; static char dir[160], cur[260], msg[100]; static u64 dbytes, t0; static short *buf, *outb;
static int cmp(const void *a, const void *b) { return strcmp(((it_t *)b)->n, ((it_t *)a)->n); }
static void load(void) { n = 0; zdirent d; for (int i = 0; n < 200 && !z_readdir(dir, i, &d); i++) if (z_ends(d.name, ".wav")) { strncpy0(L[n].n, d.name, 120); L[n].s = d.size; n++; } qsort(L, n, sizeof *L, cmp); if (sel >= n) sel = -1; }
static void hdr(u8 *h, u32 l) { memcpy(h, "RIFF", 4); *(u32 *)(h + 4) = 36 + l; memcpy(h + 8, "WAVEfmt ", 8); *(u32 *)(h + 16) = 16; *(u16 *)(h + 20) = 1; *(u16 *)(h + 22) = 1; *(u32 *)(h + 24) = 24000; *(u32 *)(h + 28) = 48000; *(u16 *)(h + 32) = 2; *(u16 *)(h + 34) = 16; memcpy(h + 36, "data", 4); *(u32 *)(h + 40) = l; }
static void draw(void) { g_clear(W, UI_BG); g_rect(W, 0, 0, W->w, 112, 0x111827); u64 sec = rec ? (z_ms() - t0) / 1000 : 0; char b[60]; snprintf(b, 60, "%02lu:%02lu", sec / 60, sec % 60); g_text2(W, 20, 18, b, rec ? 0xFCA5A5 : 0xE5E7EB, 4); g_circle(W, 196, 50, 12, rec && (z_ms() & 512) ? 0xEF4444 : 0x4B5563, 1); g_rect(W, 20, 90, W->w - 40, 10, 0x374151); int w = (W->w - 40) * MIN(peak, 32767) / 32767; g_rect(W, 20, 90, w, 10, peak > 28000 ? 0xEF4444 : 0x22C55E); ui_button(W, 230, 16, 100, 34, rec ? "Parar" : "Grabar", 2); ui_button(W, 338, 16, 40, 34, "-", 0); ui_button(W, 382, 16, 40, 34, "+", 0); snprintf(b, 60, _("Ganancia %d%%"), gain); g_text(W, 240, 60, b, 0xD1D5DB); int vis = (W->h - 160) / 22; for (int i = top; i < n && i < top + vis; i++) { int y = 120 + (i - top) * 22; if (i == sel) g_rect(W, 0, y, W->w, 22, UI_ACC2); g_text(W, 14, y + 3, L[i].n, UI_TEXT); snprintf(b, 60, "%lu s", L[i].s / 48000); g_text(W, W->w - 14 - g_textw(b), y + 3, b, UI_MUTED); } int by = W->h - 36; ui_button(W, 12, by, 84, 28, "Escuchar", sel >= 0 ? 2 : 0); ui_button(W, 102, by, 74, 28, "Borrar", 0); g_text(W, 188, by + 6, msg, UI_MUTED); zw_present(W); }
static void start(void) { int e = z_rec_start(); if (e) { strcpy(msg, _("Este equipo no tiene entrada de audio")); return; } u32 t[6]; z_time(t); snprintf(cur, 260, "%s/voz-%u%02u%02u-%02u%02u%02u.wav", dir, t[5], t[4], t[3], t[2], t[1], t[0]); f = z_open(cur, O_WRITE | O_CREATE | O_TRUNC); if (f < 0) { z_rec_stop(); strcpy(msg, z_errstr(f)); return; } u8 h[44]; hdr(h, 0); z_write(f, h, 44); dbytes = 0; rec = 1; t0 = z_ms(); peak = 0; strcpy(msg, _("Grabando...")); z_log("[prueba] grabacion iniciada"); }
static int obn; static void flush_(void) { if (obn) { z_write(f, outb, obn * 2); dbytes += obn * 2; obn = 0; } }
static void pump(void) { for (int it = 0; it < 6; it++) { long r = z_rec_read(buf, 32768); if (r < 4) break; int fr = r / 4, pk = 0; for (int i = 0; i + 1 < fr; i += 2) { int v = (buf[i * 2] + buf[i * 2 + 1] + buf[i * 2 + 2] + buf[i * 2 + 3]) / 4 * gain / 100; v = MAX(-32768, MIN(v, 32767)); outb[obn++] = v; int a = v < 0 ? -v : v; if (a > pk) pk = a; } peak = MAX(pk, peak * 3 / 4); if (obn >= 64000) flush_(); } }
static void stop(void) { pump(); z_rec_stop(); pump(); flush_(); u8 h[44]; hdr(h, dbytes); z_seek(f, 0, 0); z_write(f, h, 44); z_close(f); f = -1; rec = 0; peak = 0; z_sync(); load(); snprintf(msg, 100, _("Guardado: %lu KB"), dbytes >> 10); char m[80]; snprintf(m, 80, "[prueba] grabacion guardada %lu bytes", dbytes); z_log(m); }
int main(const char *a) { char d[120]; z_docdir(d); snprintf(dir, 160, "%s/GRABACIONES", d); z_mkdir(dir); buf = malloc(32768); outb = malloc(1 << 18); W = zw_new("Grabadora", -1, 0, 460, 360, WF_DECOR | WF_RESIZE); load(); draw(); zevent e; u64 last = 0; for (;;) { int g = z_event(&e, rec ? 40 : -1); if (g && e.type == EV_REDRAW) { draw(); continue; } if (rec) { pump(); if (z_ms() - last > 80) { last = z_ms(); draw(); } } if (!g || e.win != (u32)W->id) continue; if (e.type == EV_CLOSE) { if (rec) stop(); return 0; } if (e.type == EV_RESIZE) zw_resized(W, e.x, e.y); else if (e.type == EV_WHEEL) top = MAX(0, MIN(top - (int)e.key, n - 1)); else if (e.type == EV_KEY && e.ch == ' ') { if (rec) stop(); else start(); } else if (e.type == EV_DOWN) { int by = W->h - 36; if (e.y < 56 && e.x >= 230 && e.x < 330) { if (rec) stop(); else start(); } else if (e.y < 56 && e.x >= 338 && e.x < 378) gain = MAX(25, gain - 25); else if (e.y < 56 && e.x >= 382 && e.x < 422) gain = MIN(800, gain + 25); else if (e.y >= by) { if (sel >= 0 && e.x < 96) { char p[300]; snprintf(p, 300, "%s/%s", dir, L[sel].n); z_spawn("/rd/bin/player", p); } else if (sel >= 0 && e.x < 176 && ui_confirm("Borrar", "Borrar esta grabacion?")) { char p[300]; snprintf(p, 300, "%s/%s", dir, L[sel].n); z_unlink(p); z_sync(); load(); } } else if (e.y >= 120) { int i = top + (e.y - 120) / 22; sel = i < n ? i : -1; } } else continue; draw(); } }
